B.kU=s(["\u043d","\u043f","\u0432","\u0441","\u0447","\u043f","\u0441"],t.s)
B.aoi=new A.a9("Este aplicativo foi desenvolvido por meio de um projeto de extens\xe3o universit\xe1ria, resultado de uma iniciativa conjunta dos departamentos de Ci\xeancia da Computa\xe7\xe3o e Zootecnia da Universidade Federal de S\xe3o Jo\xe3o del Rei, Coordenada pelos professores Jana\xedna Azevedo Martuscello e Acir M. Soares Jr.",null,null,null,null,null,null,null,null)
B.ao8=new A.a9("Com o uso de smartphones, produtores rurais podem registrar imagens de forrageiras em suas propriedades para receber an\xe1lises e recomenda\xe7\xf5es t\xe9cnicas diretamente de especialistas na universidade.",null,null,null,null,null,null,null,null)
B.ao5=new A.a9("A partir do envio de 5 fotos de uma pastagem (ver exemplos), \xe9 feita a identifica\xe7\xe3o da forrageira. O aplicativo tamb\xe9m utiliza a localiza\xe7\xe3o do dispositivo (com autoriza\xe7\xe3o do usu\xe1rio) para mapear a regi\xe3o de pastagem e incluir recomenda\xe7\xf5es personalizadas para a variedade identificada.",null,null,null,null,null,null,null,null)
B.anU=new A.a9("Al\xe9m de apoiar a\xe7\xf5es extensionistas, a base de dados gerada pelo uso do aplicativo contribuir\xe1 para pesquisas sobre o mapeamento do plantio de variedades forrageiras e para a automa\xe7\xe3o da identifica\xe7\xe3o dessas variedades por modelos de intelig\xeancia artificial.",null,null,null,null,null,null,null,null)
B.anP=new A.a9('O projeto tem como objetivo aproximar produtores rurais, pesquisadores e especialistas por meio da tecnologia e est\xe1 inserido no programa de extens\xe3o "Empreendedorismo Digital: saberes computacionais para aprimoramento de institui\xe7\xf5es e gera\xe7\xe3o de inova\xe7\xf5es", coordenado pelo professor Dr. D\xe1rlinton Barbosa Feres Carvalho, do Departamento de Ci\xeancia da Computa\xe7\xe3o.',null,null,null,null,null,null,null,null)
B.a5d=s([B.M,B.aoi,B.M,B.ao8,B.M,B.ao5,B.M,B.anU,B.M,B.anP],t.p)
